CREATE TABLE `velix_production_runs` (`id` text PRIMARY KEY NOT NULL, `project_id` text NOT NULL REFERENCES `video_projects`(`id`) ON DELETE CASCADE, `brief` text NOT NULL, `contract_version` integer NOT NULL DEFAULT 1, `status` text NOT NULL, `estimated_cost_usd` real NOT NULL DEFAULT 0, `actual_cost_usd` real NOT NULL DEFAULT 0, `created_at` text NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')), `updated_at` text NOT NULL DEFAULT (datetime('now')))
